import React from 'react';

import PohBadge, { BadgeVariant, IPohBadgeProps } from '@ui-kit/Badge/Badge';

import { obstacleCategoryNameResource } from '../../@resources/obstacles.resource';
import { ObstacleCategory } from '../../@types/obstacles.types';

interface IObstacleCategoryBadgeProps extends IPohBadgeProps {
  category: ObstacleCategory;
}

const ObstacleCategoryBadge: React.FC<IObstacleCategoryBadgeProps> = ({ category, ...rest }) => {
  const badgeTypeForCategory: Record<ObstacleCategory, BadgeVariant> = {
    [ObstacleCategory.CategoryNo]: BadgeVariant.Secondary,
    [ObstacleCategory.Category1a]: BadgeVariant.Success,
    [ObstacleCategory.Category1b]: BadgeVariant.Primary,
    [ObstacleCategory.Category2a]: BadgeVariant.Warning,
    [ObstacleCategory.Category2b]: BadgeVariant.Warning,
    [ObstacleCategory.Category3a]: BadgeVariant.Danger,
    [ObstacleCategory.Category3b]: BadgeVariant.Danger,
    [ObstacleCategory.Category4a]: BadgeVariant.Dark,
    [ObstacleCategory.Category4b]: BadgeVariant.Dark,
    [ObstacleCategory.Category5a]: BadgeVariant.Dark,
    [ObstacleCategory.Category5b]: BadgeVariant.Dark,
    [ObstacleCategory.Category6a]: BadgeVariant.Dark,
    [ObstacleCategory.Category6b]: BadgeVariant.Dark,
  };

  return (
    <PohBadge as="small" variant={badgeTypeForCategory[category]} {...rest}>
      {obstacleCategoryNameResource[category]}
    </PohBadge>
  );
};

export default ObstacleCategoryBadge;
